'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const K = input[1];
const dolls = input.slice(2, 2 + N).sort((a, b) => a - b);

function ceilDiv(a, b) {
  let q = Math.floor(a / b);
  if (q * b < a) q++;
  return q;
}

let dpPrev = new Float64Array(N + 1);
dpPrev.fill(Infinity);
dpPrev.fill(0, 0, 1);

let answer = Infinity;

for (let pairs = 0; pairs < K; pairs++) {
  const slopes = [];
  const intercepts = [];
  const starts = [];
  let head = 0;
  let length = 0;

  const dpNext = pairs + 1 < K ? new Float64Array(N + 1) : null;
  if (dpNext) dpNext.fill(Infinity);

  for (let i = 1; i <= N; i++) {
    const x = dolls[i - 1];

    // Complete a pair using a previously selected first doll.
    let candidate = Infinity;
    if (length > 0) {
      while (head + 1 < length && starts[head + 1] <= x) head++;
      candidate = x * x + slopes[head] * x + intercepts[head];
    }

    if (dpNext) {
      dpNext[i] = Math.min(dpNext[i - 1], candidate);
    } else if (i <= N - K) {
      answer = Math.min(answer, candidate);
    }

    // Add this doll as the first doll of a pair.
    const base = dpPrev[i - 1];
    if (base !== Infinity) {
      const m = -2 * x;
      const b = base + x * x;

      while (length > 0) {
        const last = length - 1;

        if (slopes[last] === m) {
          if (intercepts[last] <= b) break;
          length--;
          if (head >= length) head = Math.max(0, length - 1);
          continue;
        }

        const start = ceilDiv(b - intercepts[last], slopes[last] - m);
        if (start <= starts[last]) {
          length--;
          if (head >= length) head = Math.max(0, length - 1);
        } else {
          slopes[length] = m;
          intercepts[length] = b;
          starts[length] = start;
          length++;
          break;
        }
      }

      if (length === 0) {
        slopes[0] = m;
        intercepts[0] = b;
        starts[0] = -Infinity;
        length = 1;
        head = 0;
      }
    }
  }

  if (dpNext) dpPrev = dpNext;
}

console.log(String(answer));
